import { useSyncExternalStore } from 'react'
import type { ProjectConfig } from '../../data/data_types'
import { dataService, type DataService } from '../../services/data/data_service'

const snapshots = new WeakMap<DataService, ProjectConfig | null>()

function isSameProjectConfig(first: ProjectConfig | null, second: ProjectConfig | null) {
    return first?.actionsFolder === second?.actionsFolder
        && first?.archivedFolder === second?.archivedFolder
        && first?.backgroundShade === second?.backgroundShade
        && first?.cardTypes === second?.cardTypes
        && first?.diffCommand === second?.diffCommand
        && first?.projectFolder === second?.projectFolder
        && first?.pushMode === second?.pushMode
        && first?.releasesFolder === second?.releasesFolder
        && first?.states === second?.states
        && first?.workingFolder === second?.workingFolder
}

function getProjectConfigSnapshot(service: DataService): ProjectConfig | null {
    const nextSnapshot = service.getConfig()
    const currentSnapshot = snapshots.get(service)
    if (snapshots.has(service) && isSameProjectConfig(currentSnapshot ?? null, nextSnapshot)) return currentSnapshot ?? null

    snapshots.set(service, nextSnapshot)

    return nextSnapshot
}

/** Subscribe to project config exposed through the data service. */
export function useProjectConfig(service: DataService = dataService): ProjectConfig | null {
    return useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener('changed', onStoreChange)

            return () => service.removeEventListener('changed', onStoreChange)
        },
        () => getProjectConfigSnapshot(service),
        () => getProjectConfigSnapshot(service),
    )
}

import { Box, IconButton, InputAdornment, Popover, TextField, Tooltip } from '@mui/material'
import type { MouseEvent } from 'react'
import { useCallback, useEffect, useRef, useState } from 'react'
import Magnify from 'mdi-material-ui/Magnify'
import {
    GLOBAL_SEARCH_SHORTCUT_BINDING,
    SEARCH_OPEN_REQUESTED_EVENT,
    searchOpenService,
} from '../../../services/search/search_open_service'
import type { SearchRegexpAgent } from '../../../services/search/search_types'
import { formatShortcut } from '../../../services/shortcuts/keyboard_platform'
import { NO_DRAG_REGION } from '../drag_region'
import { SearchPanel } from './search_panel'

const RESULTS_WIDTH = 460

interface SearchControlProps {
    isMobile?: boolean
    /** Builds a RegExp from the current query; defaults to the not-yet-available agent. */
    regexpAgent?: SearchRegexpAgent
}

/** Lightweight search launcher that mounts data-aware search only while open. */
export function SearchControl(props: SearchControlProps) {
    const { isMobile = false, regexpAgent } = props
    const [query, setQuery] = useState('')
    const [desktopOpen, setDesktopOpen] = useState(false)
    const [searchAnchorElement, setSearchAnchorElement] = useState<HTMLElement | null>(null)
    const mobileButtonElement = useRef<HTMLButtonElement | null>(null)
    const shortcutLabel = formatShortcut(GLOBAL_SEARCH_SHORTCUT_BINDING)

    const handleOpenRequested = useCallback(() => {
        if (!isMobile) {
            setDesktopOpen(true)
            return
        }

        const anchorElement = mobileButtonElement.current
        if (!anchorElement) throw new Error('Cannot open mobile search without its anchor button')

        setSearchAnchorElement(anchorElement)
    }, [isMobile])

    useEffect(() => {
        searchOpenService.addEventListener(SEARCH_OPEN_REQUESTED_EVENT, handleOpenRequested)

        return () => searchOpenService.removeEventListener(SEARCH_OPEN_REQUESTED_EVENT, handleOpenRequested)
    }, [handleOpenRequested])

    const openDesktop = () => {
        setDesktopOpen(true)
    }

    const closeDesktop = () => {
        setDesktopOpen(false)
    }

    const openMobile = (event: MouseEvent<HTMLElement>) => {
        setSearchAnchorElement(event.currentTarget)
    }

    const closeMobile = () => {
        setSearchAnchorElement(null)
    }

    const updateQuery = (nextQuery: string) => {
        setQuery(nextQuery)
    }

    if (!isMobile) {
        if (desktopOpen) {
            return (
                <SearchPanel
                    initialQuery={query}
                    onClose={closeDesktop}
                    onQueryChange={updateQuery}
                    regexpAgent={regexpAgent}
                />
            )
        }

        return (
            <TextField
                fullWidth
                onFocus={openDesktop}
                placeholder="Search cardsâ€¦"
                size="small"
                slotProps={{
                    htmlInput: { 'aria-label': 'Search project', readOnly: true },
                    input: {
                        endAdornment: (
                            <InputAdornment position="end">
                                <Box
                                    component="span"
                                    sx={{
                                        border: 1,
                                        borderColor: 'divider',
                                        borderRadius: 0.5,
                                        color: 'text.disabled',
                                        fontSize: 10.5,
                                        lineHeight: 1.4,
                                        px: 0.75,
                                    }}
                                >
                                    {shortcutLabel}
                                </Box>
                            </InputAdornment>
                        ),
                        startAdornment: (
                            <InputAdornment position="start">
                                <Magnify fontSize="small" />
                            </InputAdornment>
                        ),
                        sx: {
                            bgcolor: 'background.default',
                            borderRadius: 99,
                            fontSize: 13,
                            height: 32,
                            '& fieldset': { borderColor: 'divider' },
                        },
                    },
                }}
                style={NO_DRAG_REGION}
                value={query}
                variant="outlined"
            />
        )
    }

    return (
        <>
            <Tooltip title="Search">
                <IconButton
                    aria-label="Search"
                    onClick={openMobile}
                    ref={mobileButtonElement}
                    size="small"
                    sx={{ height: 34, width: 34 }}
                >
                    <Magnify />
                </IconButton>
            </Tooltip>
            <Popover
                anchorEl={searchAnchorElement}
                anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
                disableAutoFocus
                onClose={closeMobile}
                open={!!searchAnchorElement}
                slotProps={{paper: { sx: { mt: 0.5, overflow: 'visible', p: 1, width: `min(${RESULTS_WIDTH}px, calc(100vw - 32px))` } }}}
                transformOrigin={{ horizontal: 'right', vertical: 'top' }}
            >
                {searchAnchorElement ? (
                    <SearchPanel
                        initialQuery={query}
                        onClose={closeMobile}
                        onQueryChange={updateQuery}
                        regexpAgent={regexpAgent}
                    />
                ) : null}
            </Popover>
        </>
    )
}

